<?php
$user=current_user();
if(request_method('POST')){try{verify_csrf();$action=post_string('action');if($action==='read'){$id=(int)($_POST['notification_id']??0);db()->prepare('UPDATE notifications SET is_read=1 WHERE notification_id=? AND user_id=?')->execute([$id,$user['user_id']]);}elseif($action==='read_all'){db()->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?')->execute([$user['user_id']]);}redirect_to('notifications');}catch(Throwable $e){flash('notification',$e->getMessage(),'danger');redirect_to('notifications');}}
$stmt=db()->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY is_read,created_at DESC LIMIT 200');$stmt->execute([$user['user_id']]);$rows=$stmt->fetchAll();
?>
<div class="page-header"><div><h2>Notifications</h2><p>Appointments, queue updates, reports, payments and follow-up alerts.</p></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="read_all"><button class="btn btn-light">Mark all read</button></form></div><div class="card"><?php if($rows):?><?php foreach($rows as $r):?><div style="display:flex;justify-content:space-between;gap:14px;padding:15px 0;border-bottom:1px solid var(--line);<?=!$r['is_read']?'background:#f8fbff':''?>"><div style="display:flex;gap:12px"><div class="stat-icon" style="width:40px;height:40px;font-size:16px;--stat-color:<?=!$r['is_read']?'#2563eb':'#667085'?>">●</div><div><strong><?=e($r['title'])?></strong><?php if(!$r['is_read']):?> <span class="badge badge-info">New</span><?php endif;?><p class="text-muted mb-0"><?=e($r['message'])?></p><small class="text-muted"><?=format_date($r['created_at'],'d M Y, h:i A')?></small></div></div><div class="actions"><?php if($r['related_page']):?><a class="btn btn-light btn-sm" href="<?=e(route_url($r['related_page']))?>">Open</a><?php endif;?><?php if(!$r['is_read']):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="read"><input type="hidden" name="notification_id" value="<?=$r['notification_id']?>"><button class="btn btn-light btn-sm">Mark read</button></form><?php endif;?></div></div><?php endforeach;?><?php else:?><div class="empty-state"><div class="empty-icon">◉</div><p>No notifications yet.</p></div><?php endif;?></div>
